/* ---------------------------------------------------------------- layout -- */

/**
 * fieldnotes in four columns with saved spans: api two columns wide between
 * web and docs at one each. The cards that frame it show the middle two
 * columns, api whole, and the top bar over them (its workspace tabs; the
 * brand and the tools are outside), so no edge cuts a tile.
 */
const SPANS = { gridTemplateColumns: `${columnWidth(4)}fr ${columnWidth(4) * 2 + SPACE}fr ${columnWidth(4)}fr` };
/** The part of the window those cards show across: from the gap after web to the gap before docs. */
const SPANS_VIEW = { left: columnGap(4, 1), right: columnGap(4, 3) };

const spanTiles = () => [
  <SessionTile key="web" id="web" capture="web-57" kbd="⌘1" />,
  <SessionTile key="api" id="api" capture="api-86" kbd="⌘2" />,
  <SessionTile key="docs" id="docs" capture="docs-57" kbd="⌘3" />,
];

/**
 * A resize in progress (src/grid/TileResizeHandles.tsx): api's right edge
 * dragged half a column in. The outline shows the tile as it will be once
 * saved, 1.5 columns of the grid's half-column tracks at its row's height,
 * the grid's 10px spacing between tracks.
 */
export function LayoutShot() {
  const margin = 20;
  const layer = useRef<HTMLDivElement>(null);
  const tile = useBoxIn(layer, (scene) => scene.querySelectorAll(".grid > .tile")[1]);
  const from = 2;
  const span = { c: 1.5, r: 1 };
  // The grid's tracks are half columns, with SPACE between them.
  const track = tile ? (tile.width - SPACE * (from * 2 - 1)) / (from * 2) : 0;
  return (
    <Shot id="spaces" width={SPANS_VIEW.right - SPANS_VIEW.left} height={margin + betweenLines(1, 0, 33)}>
      <AppWindow box={{ left: -SPANS_VIEW.left, top: margin, ...WIN_SIZE }}>
        <ActiveCanvas initial={1} style={SPANS} tiles={spanTiles()} />
        <WindowLayer layerRef={layer}>
          {tile ? (
            <div
              className="tile-resize-ghost"
              style={{
                left: tile.left,
                top: tile.top,
                width: track * span.c * 2 + SPACE * (span.c * 2 - 1),
                height: tile.height,
              }}
              aria-hidden="true"
            >
              <span>
                {span.c} × {span.r}
              </span>
            </div>
          ) : null}
        </WindowLayer>
      </AppWindow>
    </Shot>
  );
}

/* ------------------------------------------------------------- snapshots -- */

/** The window framed on the workspace tabs and the settings dropdown under them. */
const MENU_BOX: Box = { left: -SPANS_VIEW.left, top: 20, ...WIN_SIZE };
/** Room the card keeps under the dropdown, at least. */
const MENU_MARGIN = 24;

/**
 * fieldnotes' settings open under its tab, with Snapshots unfolded or a
 * restore preview open. The card is as tall as the dropdown needs, so the
 * whole panel always shows (folding or unfolding a section resizes it), and
 * ends between two of api's terminal rows.
 */
function WorkspaceMenuShot({
  height: initialHeight,
  previewing,
}: {
  height: number;
  previewing?: string;
}) {
  const layer = useRef<HTMLDivElement>(null);
  const tab = useBoxIn(layer, (scene) => scene.querySelector(".ws-tab-active"));
  const [menuHeight, setMenuHeight] = useState<number | null>(null);
  const height =
    tab && menuHeight
      ? MENU_BOX.top + cleanY(Math.ceil(tab.top + tab.height + 5 + menuHeight + MENU_MARGIN), 1)
      : initialHeight;
  return (
    <Shot id="spaces" width={SPANS_VIEW.right - SPANS_VIEW.left} height={height}>
      <AppWindow box={MENU_BOX}>
        <ActiveCanvas initial={1} style={SPANS} tiles={spanTiles()} />
        <WindowLayer layerRef={layer}>
          {tab ? (
            <WorkspaceMenu
              tab={tab}
              snapshots
              previewing={previewing ?? null}
              onHeight={setMenuHeight}
            />
          ) : null}
        </WindowLayer>
      </AppWindow>
    </Shot>
  );
}

export function SnapshotShot() {
  return <WorkspaceMenuShot height={559} />;
}

export function RestoreShot() {
  return <WorkspaceMenuShot height={814} previewing="saved" />;
}
